window.Mustache = (function () {
  function escapeHtml(value) {
    return String(value == null ? "" : value).replace(/[&<>"']/g, function (char) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;"
      }[char];
    });
  }

  function lookup(path, context) {
    var current = context;
    while (current) {
      if (path === ".") {
        return current.view;
      }
      var parts = path.split(".");
      var value = current.view;
      var found = true;
      for (var i = 0; i < parts.length; i += 1) {
        if (value != null && Object.prototype.hasOwnProperty.call(value, parts[i])) {
          value = value[parts[i]];
        } else {
          found = false;
          break;
        }
      }
      if (found) {
        return value;
      }
      current = current.parent;
    }
    return "";
  }

  function renderSections(template, context) {
    return template
      .replace(/{{#\s*([^}]+)\s*}}([\s\S]*?){{\/\s*\1\s*}}/g, function (_, key, inner) {
        var value = lookup(key.trim(), context);
        if (Array.isArray(value)) {
          return value
            .map(function (item, index) {
              var view = typeof item === "object" && item !== null ? Object.assign({}, item) : { ".": item };
              view.index = index;
              view.index_human = index + 1;
              return renderTemplate(inner, { view: view, parent: context });
            })
            .join("");
        }
        if (value && typeof value === "object") {
          return renderTemplate(inner, { view: value, parent: context });
        }
        return value ? renderTemplate(inner, context) : "";
      })
      .replace(/{{\^\s*([^}]+)\s*}}([\s\S]*?){{\/\s*\1\s*}}/g, function (_, key, inner) {
        var value = lookup(key.trim(), context);
        var isEmptyArray = Array.isArray(value) && value.length === 0;
        var isFalsy = !value;
        return isFalsy || isEmptyArray ? renderTemplate(inner, context) : "";
      });
  }

  function renderVariables(template, context) {
    return template
      .replace(/{{{\s*([^}]+)\s*}}}/g, function (_, key) {
        var value = lookup(key.trim(), context);
        return value == null ? "" : String(value);
      })
      .replace(/{{\s*([^}]+)\s*}}/g, function (_, key) {
        return escapeHtml(lookup(key.trim(), context));
      });
  }

  function renderTemplate(template, context) {
    return renderVariables(renderSections(template, context), context);
  }

  return {
    render: function (template, view) {
      return renderTemplate(template, { view: view || {}, parent: null });
    }
  };
})();
